package com.oms.order.controller;
import com.oms.order.service.*;
import com.ruoyi.common.core.domain.R;
import com.ruoyi.common.core.web.domain.AjaxResult;
import com.ruoyi.common.core.web.page.TableDataInfo;
import com.ruoyi.common.security.annotation.*;
import com.ruoyi.common.security.utils.SecurityUtils;
import org.springframework.web.bind.annotation.*;
import javax.annotation.Resource;
import java.util.*;
import static com.oms.order.service.OrderValues.*;

@RestController @RequestMapping("/orders")
public class OrderController {
    @Resource private OrderPlatformShippingService platformShipping;
    @RequiresPermissions("order:order:query") @GetMapping("/shipments/{id}/platform-shipping") public AjaxResult platformShipping(@PathVariable long id){return AjaxResult.success(platformShipping.report(company(),id));}
    @RequiresPermissions("order:shipment:platformShipping") @PostMapping("/shipments/{id}/platform-shipping") public AjaxResult platformShippingSubmit(@PathVariable long id){return AjaxResult.success(platformShipping.enqueue(company(),id,SecurityUtils.getUsername()));}
    @RequiresPermissions("order:shipment:platformShipping") @PostMapping("/shipments/{id}/platform-shipping/{task}/{action}") public AjaxResult platformShippingAction(@PathVariable long id,@PathVariable long task,@PathVariable String action){platformShipping.action(company(),id,task,action.toUpperCase(java.util.Locale.ROOT),SecurityUtils.getUsername());return AjaxResult.success(platformShipping.report(company(),id));}
    @RequiresPermissions("order:shipment:platformConfig") @GetMapping("/platform-shipping-config/{channel}") public AjaxResult platformShippingConfig(@PathVariable long channel){return AjaxResult.success(platformShipping.configuration(company(),channel));}
    @RequiresPermissions("order:shipment:platformConfig") @PostMapping("/platform-shipping-config/{channel}") public AjaxResult platformShippingConfigSave(@PathVariable long channel,@RequestBody Map<String,Object> body){return AjaxResult.success(platformShipping.saveConfiguration(company(),channel,body,SecurityUtils.getUsername()));}
    @Resource private OrderIssueService issues;
    @RequiresPermissions("order:order:query") @PostMapping("/business/{id}/issues/recheck") public AjaxResult recheckIssues(@PathVariable long id){return AjaxResult.success(issues.recheck(company(),id));}
    @RequiresPermissions("order:order:query") @GetMapping("/business/{id}/issues") public AjaxResult issues(@PathVariable long id){return AjaxResult.success(issues.report(company(),id));}
    @RequiresPermissions("order:order:review") @PostMapping("/business/{id}/issues/{issue}/acknowledge") public AjaxResult acknowledge(@PathVariable long id,@PathVariable long issue,@RequestBody Map<String,Object> body){issues.acknowledge(company(),id,issue,text(body,"note"),SecurityUtils.getUsername());return AjaxResult.success();}
    @Resource private OrderShipmentReceiptReviewService receiptReviews;
    @RequiresPermissions("order:order:query") @GetMapping("/shipments/{id}/receipt-reviews") public AjaxResult receiptReviews(@PathVariable long id){return AjaxResult.success(receiptReviews.report(company(),id));}
    @RequiresPermissions("order:shipment:receiptReview") @PostMapping("/shipments/{id}/receipt-reviews/{review}") public AjaxResult decideReceiptReview(@PathVariable long id,@PathVariable long review,@RequestBody Map<String,Object> body){return AjaxResult.success(receiptReviews.decide(company(),id,review,body,SecurityUtils.getUsername()));}
    @Resource private OrderShipmentPackageService packages;
    @Resource private OrderShipmentReceiptService receipts;
    @RequiresPermissions("order:shipment:package") @PostMapping("/shipments/{id}/packages") public AjaxResult packageRegister(@PathVariable long id,@RequestBody Map<String,Object> body){return AjaxResult.success(packages.register(company(),id,body,SecurityUtils.getUsername()));}
    @RequiresPermissions("order:shipment:receipt") @PostMapping("/shipments/{id}/reconcile-receipts") public AjaxResult receiptReconcile(@PathVariable long id){return AjaxResult.success(receipts.reconcile(company(),id,SecurityUtils.getUsername()));}
    @Resource private OrderVirtualOutboundService virtualOutbound;
    @RequiresPermissions("order:shipment:virtualOutbound") @PostMapping("/shipments/virtual-outbound-preview") public AjaxResult virtualPreview(@RequestBody Map<String,Object> body){return AjaxResult.success(virtualOutbound.preview(company(),body));}
    @RequiresPermissions("order:shipment:virtualOutbound") @PostMapping("/shipments/virtual-outbound") public AjaxResult virtualSubmit(@RequestBody Map<String,Object> body){return AjaxResult.success(virtualOutbound.submit(company(),body,SecurityUtils.getUsername()));}
    @RequiresPermissions("order:shipment:virtualOutbound") @PostMapping("/shipments/{id}/retry-virtual-outbound") public AjaxResult virtualRetry(@PathVariable long id,@RequestBody Map<String,Object> body){require(body.containsKey("control_version"),"缺少发货单版本");return AjaxResult.success(virtualOutbound.retry(company(),id,number(body,"control_version"),SecurityUtils.getUsername()));}
    @RequiresPermissions("order:shipment:virtualOutbound") @PostMapping("/shipments/{id}/query-virtual-outbound") public AjaxResult virtualQuery(@PathVariable long id){return AjaxResult.success(virtualOutbound.reconcile(company(),id,SecurityUtils.getUsername()));}
    @Resource private OrderShipmentDispatchService shipmentDispatch;
    @RequiresPermissions("order:shipment:dispatch") @PostMapping("/shipments/dispatch-preview") public AjaxResult dispatchPreview(@RequestBody Map<String,Object> body){return AjaxResult.success(shipmentDispatch.preview(company(),body));}
    @RequiresPermissions("order:shipment:dispatch") @PostMapping("/shipments/dispatch") public AjaxResult dispatchShipments(@RequestBody Map<String,Object> body){return AjaxResult.success(shipmentDispatch.submit(company(),body,SecurityUtils.getUsername()));}
    @RequiresPermissions("order:shipment:queryWarehouse") @PostMapping("/shipments/{id}/query-warehouse") public AjaxResult queryShipmentWarehouse(@PathVariable long id){return AjaxResult.success(shipmentDispatch.query(company(),id,SecurityUtils.getUsername()));}
    @RequiresPermissions("order:shipment:dispatch") @PostMapping("/shipments/{id}/continue-dispatch") public AjaxResult continueDispatch(@PathVariable long id,@RequestBody Map<String,Object> body){String c=company();Map<String,Object> s=shipments.detail(c,id);require(body.containsKey("control_version")&&number(s,"control_version")==number(body,"control_version"),"发货单已变化，请刷新核对");require("PENDING".equals(text(s,"wms_dispatch_state")),"仅可执行原待下发任务；结果不明请核对仓库");shipmentDispatch.process(c,id);return AjaxResult.success(shipments.detail(c,id));}
    @Resource private OrderCarrierService carriers;
    @RequiresPermissions("order:pull:config") @GetMapping("/carrier-catalog") public AjaxResult carrierCatalog(){return AjaxResult.success(carriers.catalog(company()));}
    @RequiresPermissions("order:pull:config") @PostMapping("/carriers") public AjaxResult saveCarrier(@RequestBody Map<String,Object> body){carriers.saveCarrier(company(),body,SecurityUtils.getUsername());return AjaxResult.success();}
    @RequiresPermissions("order:pull:config") @GetMapping("/carrier-configs") public AjaxResult carrierConfigs(){return AjaxResult.success(carriers.configurations(company()));}
    @RequiresPermissions("order:pull:config") @PostMapping("/carrier-configs") public AjaxResult saveCarrierConfig(@RequestBody Map<String,Object> body){carriers.saveConfiguration(company(),body,SecurityUtils.getUsername());return AjaxResult.success();}
    @RequiresPermissions("order:order:query") @GetMapping("/shipments/{id}/carrier-options") public AjaxResult carrierOptions(@PathVariable long id){return AjaxResult.success(carriers.options(company(),id));}
    @RequiresPermissions("order:shipment:carrier") @PostMapping("/shipments/match-carrier") public AjaxResult matchCarriers(@RequestBody Map<String,Object> body){return AjaxResult.success(carriers.match(company(),body,SecurityUtils.getUsername()));}
    @Resource private OrderAutoAllocationService automaticAllocation;
    @Resource private OrderAutoAllocationWorker automaticWorker;
    @RequiresPermissions("order:order:allocate") @PostMapping("/business/{id}/auto-allocation/{action}") public AjaxResult automaticAction(@PathVariable long id,@PathVariable String action,@RequestBody Map<String,Object> body){require(body.containsKey("control_version"),"请刷新订单后操作");Map<String,Object> result=automaticAllocation.action(company(),id,action,number(body,"control_version"),SecurityUtils.getUsername());if(!"pause".equals(action))automaticWorker.kick(company());return AjaxResult.success(result);}
    @Resource private OrderAllocationService allocations;
    @Resource private OrderShipmentService shipments;
    @RequiresPermissions("order:order:list") @GetMapping("/shipments/list") public TableDataInfo shipments(@RequestParam(defaultValue="") String number,@RequestParam(required=false) Long channelId,@RequestParam(defaultValue="") String status,@RequestParam(defaultValue="") String store,@RequestParam(defaultValue="") String sku,@RequestParam(defaultValue="") String dispatchState,@RequestParam(defaultValue="1") int pageNum,@RequestParam(defaultValue="20") int pageSize){return shipments.list(company(),number,channelId,status,store,sku,dispatchState,pageNum,pageSize);}
    @RequiresPermissions("order:order:query") @GetMapping("/shipments/{id}") public AjaxResult shipment(@PathVariable long id){return AjaxResult.success(shipments.detail(company(),id));}
    @RequiresPermissions("order:order:allocate") @PostMapping("/business/{id}/shipments") public AjaxResult generateShipments(@PathVariable long id,@RequestBody Map<String,Object> body){require(body.containsKey("control_version"),"请刷新订单后重试");return AjaxResult.success(shipments.generate(company(),id,number(body,"control_version"),SecurityUtils.getUsername()));}
    @RequiresPermissions("order:pull:config") @GetMapping("/allocation-configs") public AjaxResult allocationConfigs(){return AjaxResult.success(allocations.configurations(company()));}
    @RequiresPermissions("order:pull:config") @GetMapping("/allocation-config/{channel}") public AjaxResult allocationConfig(@PathVariable long channel){return AjaxResult.success(allocations.configuration(company(),channel));}
    @RequiresPermissions("order:pull:config") @PostMapping("/allocation-config") public AjaxResult saveAllocationConfig(@RequestBody Map<String,Object> body){allocations.save(company(),body,SecurityUtils.getUsername());return AjaxResult.success();}
    @RequiresPermissions("order:order:allocate") @PostMapping("/business/allocation-preview") public AjaxResult allocationPreview(@RequestBody Map<String,Object> body){return AjaxResult.success(allocations.preview(company(),body));}
    @RequiresPermissions("order:order:allocate") @PostMapping("/business/allocate-batch") public AjaxResult allocateBatch(@RequestBody Map<String,Object> body){return AjaxResult.success(allocations.allocate(company(),body,SecurityUtils.getUsername()));}
    @Resource private OrderImmediateWork cutoffWork;
    @Resource private OrderCutoffService cutoff;
    @RequiresPermissions("order:order:query") @GetMapping("/business/{id}/cutoff") public AjaxResult cutoffReport(@PathVariable long id){return AjaxResult.success(cutoff.report(company(),id));}
    @RequiresPermissions("order:order:cutoff") @PostMapping("/business/{id}/cutoff") public AjaxResult cutoff(@PathVariable long id,@RequestBody Map<String,Object> body){String c=company();Map<String,Object> result=cutoff.request(c,id,body,SecurityUtils.getUsername());cutoffWork.cutoffReady(c,id);return AjaxResult.success(result);}
    @RequiresPermissions("order:order:cutoff") @PostMapping("/business/{id}/cutoff/retry") public AjaxResult cutoffRetry(@PathVariable long id,@RequestBody Map<String,Object> body){require(body.containsKey("control_version"),"请刷新订单后操作");String c=company();Map<String,Object> result=cutoff.retry(c,id,number(body,"control_version"),SecurityUtils.getUsername());cutoffWork.cutoffReady(c,id);return AjaxResult.success(result);}
    @Resource private OrderVoidService voids;
    @RequiresPermissions("order:order:void") @PostMapping("/business/void-batch") public AjaxResult voidBatch(@RequestBody Map<String,Object> body){List<Map<String,Object>> result=voids.request(company(),body,SecurityUtils.getUsername());coordinator.poll();for(Map<String,Object> row:result)if("CUTTING".equals(text(row,"status")))cutoffWork.cutoffReady(company(),number(row,"id"));return AjaxResult.success(result);}
    @RequiresPermissions("order:order:list") @PostMapping("/business/void-results") public AjaxResult voidResults(@RequestBody List<Long> ids){return AjaxResult.success(businessOrders.results(company(),ids));}

    @Resource private OrderAutoReviewService autoReviews;
    @RequiresPermissions("order:pull:config") @GetMapping("/review-configs") public AjaxResult reviewConfigs(){return AjaxResult.success(autoReviews.configurations(company()));}
    @RequiresPermissions("order:pull:config") @GetMapping("/review-config/{channel}") public AjaxResult reviewConfig(@PathVariable long channel){return AjaxResult.success(autoReviews.configuration(company(),channel));}
    @RequiresPermissions("order:pull:config") @PostMapping("/review-config") public AjaxResult saveReviewConfig(@RequestBody Map<String,Object> body){autoReviews.save(company(),body,SecurityUtils.getUsername());return AjaxResult.success();}
    @RequiresPermissions("order:order:query") @GetMapping("/business/{id}/review-preview") public AjaxResult reviewPreview(@PathVariable long id){return AjaxResult.success(autoReviews.preview(company(),id));}
    @RequiresPermissions("order:order:review") @PostMapping("/business/{id}/review-recheck") public AjaxResult reviewRecheck(@PathVariable long id,@RequestBody Map<String,Object> body){require(body.containsKey("control_version"),"请刷新订单后重新判定");autoReviews.recheck(company(),id,number(body,"control_version"),SecurityUtils.getUsername());return AjaxResult.success();}
    @Resource private OrderReviewService reviews;
    @RequiresPermissions("order:order:review") @PostMapping("/business/approve-batch") public AjaxResult approve(@RequestBody Map<String,Object> body){return AjaxResult.success(reviews.apply(company(),"approve",body,SecurityUtils.getUsername()));}
    @RequiresPermissions("order:order:hold") @PostMapping("/business/hold-batch") public AjaxResult hold(@RequestBody Map<String,Object> body){return AjaxResult.success(reviews.apply(company(),"hold",body,SecurityUtils.getUsername()));}
    @RequiresPermissions("order:order:hold") @PostMapping("/business/resume-batch") public AjaxResult resume(@RequestBody Map<String,Object> body){List<Map<String,Object>> result=reviews.apply(company(),"resume",body,SecurityUtils.getUsername());coordinator.poll();return AjaxResult.success(result);}

    @RequiresPermissions("order:order:query") @GetMapping("/platform/{id}/updates/events/{event}") public AjaxResult orderUpdateEvent(@PathVariable long id,@PathVariable long event){return AjaxResult.success(new OrderUpdateService(repository).event(company(),id,event));}
    @Resource private OrderShipmentWmsClient updateWarehouse;
    @RequiresPermissions("order:order:query") @GetMapping("/platform/{id}/updates") public AjaxResult orderUpdates(@PathVariable long id){return AjaxResult.success(new OrderUpdateService(repository).report(company(),id));}
    @RequiresPermissions("order:order:update") @PostMapping("/platform/{id}/updates/recipient") public AjaxResult applyRecipient(@PathVariable long id,@RequestBody Map<String,Object> body){return AjaxResult.success(new OrderUpdateService(repository,updateWarehouse).applyRecipient(company(),id,body,SecurityUtils.getUsername()));}
    @RequiresPermissions({"order:order:update","order:order:cutoff"}) @PostMapping("/platform/{id}/updates/withdraw") public AjaxResult withdrawForUpdate(@PathVariable long id,@RequestBody Map<String,Object> body){String c=company();Map<String,Object> result=new OrderUpdateService(repository).prepare(c,id,body,SecurityUtils.getUsername(),cutoff);cutoffWork.cutoffReady(c,number(repository.raw(c,id),"business_order_id"));return AjaxResult.success(result);}
    @Resource private OrderWorkspaceService workspace;
    @RequiresPermissions("order:pull:config") @GetMapping("/conversion-configs") public AjaxResult conversionConfigs(){return AjaxResult.success(workspace.conversionConfigs(company()));}
    @RequiresPermissions("order:pull:config") @PostMapping("/conversion-configs") public AjaxResult saveConversionConfig(@RequestBody Map<String,Object> body){workspace.saveConversion(company(),body,SecurityUtils.getUsername());return AjaxResult.success();}
    @Resource private OrderCoordinator coordinator;
    @Resource private OrderRepository repository;
    @Resource private OrderProductMatchService productMatch;
    @Resource private OrderBusinessService businessOrders;
    private String company(){return OrderValues.company(SecurityUtils.getLoginUser().getCompanyCode());}
    @InnerAuth @PostMapping("/internal/scan-all") public R<Map<String,Object>> scan(){return R.ok(coordinator.poll());}
    @RequiresPermissions("order:order:list") @GetMapping("/catalog") public AjaxResult catalog(){return AjaxResult.success(workspace.catalog(company()));}
    @RequiresPermissions("order:pull:config") @GetMapping("/configs") public AjaxResult configs(){return AjaxResult.success(workspace.configs(company()));}
    @RequiresPermissions("order:pull:config") @PostMapping("/configs") public AjaxResult save(@RequestBody Map<String,Object> body){workspace.save(company(),body,SecurityUtils.getUsername());return AjaxResult.success();}
    @RequiresPermissions("order:pull:config") @PostMapping("/configs/verify-source") public AjaxResult verifySource(@RequestBody Map<String,Object> body){return AjaxResult.success(workspace.verifySource(company(),body));}
    @RequiresPermissions("order:pull:execute") @GetMapping("/backfill-options") public AjaxResult backfillOptions(){Map<String,Object> values=new LinkedHashMap<>();values.put("server_time",java.time.LocalDateTime.now().withNano(0).format(TIME));values.put("max_tids",100);return AjaxResult.success(values);}
    @RequiresPermissions("order:pull:execute") @PostMapping("/backfill") public AjaxResult backfill(@RequestBody Map<String,Object> body){Map<String,Object> result=workspace.backfillRequest(company(),body,SecurityUtils.getUsername());coordinator.poll();return AjaxResult.success(result);}
    @RequiresPermissions("order:order:list") @GetMapping("/tasks/{id:[0-9]+}") public AjaxResult pullTask(@PathVariable long id){return AjaxResult.success(workspace.pullTask(company(),id));}
    @RequiresPermissions("order:order:list") @GetMapping("/tasks/{id}/items") public TableDataInfo pullItems(@PathVariable long id,@RequestParam(defaultValue="") String result,@RequestParam(defaultValue="1") int pageNum,@RequestParam(defaultValue="20") int pageSize){return workspace.pullItems(company(),id,result,pageNum,pageSize);}
    @RequiresPermissions("order:pull:execute") @PostMapping("/tasks/{id}/retry-items") public AjaxResult retryPullItems(@PathVariable long id,@RequestBody(required=false) Map<String,Object> body){List<Long> items=new ArrayList<>();if(body!=null&&body.containsKey("item_ids")){require(body.get("item_ids") instanceof List,"失败项参数无效");for(Object value:(List<?>)body.get("item_ids"))items.add(Long.valueOf(value.toString()));}Map<String,Object> result=workspace.retryPullItems(company(),id,SecurityUtils.getUsername(),items);coordinator.poll();return AjaxResult.success(result);}
    @RequiresPermissions("order:order:retry") @PostMapping("/platform/{id}/retry") public AjaxResult retry(@PathVariable long id){workspace.retry(company(),id,SecurityUtils.getUsername());coordinator.poll();return AjaxResult.success();}
    @RequiresPermissions("order:order:retry") @PostMapping("/platform/{id}/match-product") public AjaxResult matchProduct(@PathVariable long id,@RequestBody Map<String,Object> body){productMatch.match(company(),id,body,SecurityUtils.getUsername());coordinator.poll();return AjaxResult.success();}
    @RequiresPermissions("order:order:retry") @PostMapping("/platform/retry-batch") public AjaxResult retryBatch(@RequestBody List<Long> ids){List<Map<String,Object>> result=workspace.retryBatch(company(),ids,SecurityUtils.getUsername());coordinator.poll();return AjaxResult.success(result);}
    @RequiresPermissions("order:order:list") @PostMapping("/platform/retry-results") public AjaxResult retryResults(@RequestBody List<Long> ids){return AjaxResult.success(workspace.retryResults(company(),ids));}
    @RequiresPermissions("order:order:retry") @PostMapping("/business/reserve-batch") public AjaxResult reserveBatch(@RequestBody List<Long> ids){List<Map<String,Object>> result=businessOrders.retry(company(),ids,SecurityUtils.getUsername());coordinator.poll();return AjaxResult.success(result);}
    @RequiresPermissions("order:order:list") @PostMapping("/business/reserve-results") public AjaxResult reserveResults(@RequestBody List<Long> ids){return AjaxResult.success(businessOrders.results(company(),ids));}
    @RequiresPermissions("order:pull:execute") @PostMapping("/tasks/{id}/retry") public AjaxResult retryTask(@PathVariable long id){Map<String,Object> task=workspace.pullTask(company(),id);if("TID".equals(text(task,"pull_mode"))){Map<String,Object> result=workspace.retryPullItems(company(),id,SecurityUtils.getUsername());coordinator.poll();return AjaxResult.success(result);}int changed=repository.db().update("UPDATE oms_order_pull_task SET status='PENDING',attempts=0,next_retry_at=NOW(),error_message='' WHERE company_code=? AND id=? AND status='FAILED'",company(),id);require(changed==1,"任务不存在或当前无需重试");coordinator.poll();return AjaxResult.success();}
    @RequiresPermissions("order:order:list") @GetMapping("/{view}/list") public TableDataInfo list(@PathVariable String view,@RequestParam(required=false) Long channelId,@RequestParam(defaultValue="") String tid,@RequestParam(defaultValue="") String status,@RequestParam(defaultValue="1") int pageNum,@RequestParam(defaultValue="20") int pageSize,@RequestParam(defaultValue="") String category,@RequestParam(defaultValue="") String sku,@RequestParam(defaultValue="") String from,@RequestParam(defaultValue="") String to,@RequestParam(defaultValue="0") int waitingMinutes,@RequestParam(defaultValue="") String reviewStatus,@RequestParam(defaultValue="") String processingStatus,@RequestParam(defaultValue="") String documentStatus,@RequestParam(defaultValue="") String issueCategory,@RequestParam(defaultValue="") String issueScope,@RequestParam(defaultValue="") String issueBlocking,@RequestParam(defaultValue="") String issueState,@RequestParam(defaultValue="") String updateState,@RequestParam(defaultValue="") String exchangeStatus){if("business".equals(view))return businessOrders.list(company(),channelId,tid,status,sku,from,to,waitingMinutes,pageNum,pageSize,reviewStatus,processingStatus,documentStatus,issueCategory,issueScope,issueBlocking,issueState,updateState,exchangeStatus);return workspace.list(company(),view,channelId,tid,status,pageNum,pageSize,category,sku,from,to,waitingMinutes);}
    @RequiresPermissions("order:order:query") @GetMapping("/{view}/{id}") public AjaxResult detail(@PathVariable String view,@PathVariable long id){require(Arrays.asList("platform","business").contains(view),"详情类型无效");return AjaxResult.success("business".equals(view)?businessOrders.detail(company(),id):workspace.detail(company(),id,false));}
    @RequiresPermissions("order:order:raw") @GetMapping("/platform/{id}/payload") public AjaxResult payload(@PathVariable long id){Map<String,Object> order=repository.raw(company(),id);Map<String,Object> result=new LinkedHashMap<>();result.put("latest",order.get("raw_payload"));result.put("processing",order.get("processing_payload"));return AjaxResult.success(result);}
}
